import 'package:flutter/material.dart';
import '../app_state.dart';
import 'home_page.dart';

class CheckoutPage extends StatefulWidget { const CheckoutPage({super.key}); @override State<CheckoutPage> createState()=>_CheckoutPageState(); }
class _CheckoutPageState extends State<CheckoutPage> {
 String payment='Cash';
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:AppState.instance,builder:(context,_) {final app=AppState.instance;return Scaffold(appBar:AppBar(title:const Text('Checkout')),body:app.cart.isEmpty?const Center(child:Text('Keranjang kosong.')):ListView(padding:const EdgeInsets.all(16),children:[const Text('Alamat pengiriman',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold)),const SizedBox(height:10),Card(child:ListTile(leading:const Icon(Icons.location_on,color:Colors.deepOrange),title:const Text('Alamat tujuan'),subtitle:Text(app.address),trailing:IconButton(icon:const Icon(Icons.edit_outlined),onPressed:()=>_editAddress(context)))),const SizedBox(height:22),const Text('Metode pembayaran',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold)),const SizedBox(height:8),Card(child:Column(children:[RadioListTile<String>(value:'Cash',groupValue:payment,onChanged:(v)=>setState(()=>payment=v!),title:const Text('Bayar tunai (COD)')),RadioListTile<String>(value:'QRIS',groupValue:payment,onChanged:(v)=>setState(()=>payment=v!),title:const Text('QRIS (simulasi)'))])),const SizedBox(height:22),const Text('Ringkasan pesanan',style:TextStyle(fontSize:19,fontWeight:FontWeight.bold)),...app.cart.map((e)=>ListTile(contentPadding:EdgeInsets.zero,title:Text('${e.menu.name} × ${e.quantity}'),trailing:Text('Rp${_money(e.menu.price*e.quantity)}'))),const Divider(),_row('Subtotal',app.subtotal),_row('Ongkir',8000),const SizedBox(height:8),_row('Total',app.total,bold:true),const SizedBox(height:20),SizedBox(height:52,child:FilledButton(onPressed:(){final total=app.total;app.placeOrder();showDialog(context:context,barrierDismissible:false,builder:(ctx)=>AlertDialog(icon:const Icon(Icons.check_circle,color:Colors.green,size:48),title:const Text('Pesanan dibuat!'),content:Text('Pesananmu tercatat dengan total Rp${_money(total)}. Pembayaran $payment masih berupa simulasi.'),actions:[FilledButton(onPressed:(){Navigator.pop(ctx);Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder: (_) => const HomePage()), (route) => false);},child:const Text('Lihat pesanan'))]));},child:const Text('KONFIRMASI PESANAN')))]));});
 Widget _row(String t,int n,{bool bold=false})=>Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(t,style:TextStyle(fontWeight:bold?FontWeight.bold:FontWeight.normal,fontSize:bold?17:14)),Text('Rp${_money(n)}',style:TextStyle(fontWeight:bold?FontWeight.bold:FontWeight.normal,fontSize:bold?18:14))]));
 String _money(int n)=>n.toString().replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'),(_)=>'.');
 Future<void> _editAddress(BuildContext context)async{final c=TextEditingController(text:AppState.instance.address);final result=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Alamat pengiriman'),content:TextField(controller:c,maxLines:3,decoration:const InputDecoration(hintText:'Masukkan alamat lengkap')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Batal')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('Simpan'))]));if(result!=null&&result.isNotEmpty){AppState.instance.address=result;await AppState.instance.saveProfile();}c.dispose();}
}
